draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // dog body
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // dog head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 30, 15, 0, 2 * Math.PI);
  ctx.stroke();

  // eyes
  ctx.beginPath();
  ctx.arc(W/2 - 5, H/2 - 40, 2, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 5, H/2 - 40, 2, 0, 2 * Math.PI);
  ctx.fill();

  // rolling motion
  ctx.save();
  ctx.translate(W/2, H/2);
  ctx.rotate(Math.sin(t) * Math.PI / 4);

  // front leg
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-15, 20);
  ctx.stroke();

  // back leg
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(15, 20);
  ctx.stroke();

  ctx.restore();

  // submission roll
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 20, 10, 0, Math.sin(t) * Math.PI);
  ctx.stroke();

  ctx.restore();
}
